import AppKit

/// Small, organ-local paintings. Core Animation transforms these immutable images;
/// neither noise nor pigment is regenerated by the animation clock.
enum BloomIllustration {
    struct Painting {
        let image: CGImage
        let bounds: CGRect
        var bytes: Int { image.bytesPerRow * image.height }
    }

    // Continuous object-space displacement, shared at coincident path endpoints.
    // The petiole at the origin is pinned so the plant's attachment graph survives.
    static func organicPath(_ path: CGPath, species: BloomPlant, flower: Bool,
                            variation: Double, amount: Double) -> CGPath {
        guard amount > 0 else { return path }
        let result = CGMutablePath()
        let narrow = [.grass,.lavender,.willow,.fern,.pine,.spruce,.cedar].contains(species)
        let amplitude = amount * (flower ? 0.027 : narrow ? 0.018 : 0.043)
        let phase = variation * 83.71
        func warp(_ p: CGPoint) -> CGPoint {
            let pin = min(1,hypot(p.x,p.y)*6)
            let x = sin(p.y*13+phase) + 0.38*sin(p.y*31+p.x*9-phase)
            let y = sin(p.x*17+p.y*8+phase*1.7)
            return CGPoint(x:p.x + amplitude*pin*x + p.y*amount*0.036*sin(phase),
                           y:p.y + amplitude*pin*y*0.48)
        }
        var current = CGPoint.zero, start = CGPoint.zero
        func curve(_ end: CGPoint, _ c1: CGPoint, _ c2: CGPoint) {
            // Sample the original curve before warping: control-point jitter alone
            // cannot produce correlated small contour inflections.
            let origin = current
            for step in 1...16 {
                let t = Double(step)/16, q = 1-t
                let p = CGPoint(x:q*q*q*origin.x+3*q*q*t*c1.x+3*q*t*t*c2.x+t*t*t*end.x,
                                y:q*q*q*origin.y+3*q*q*t*c1.y+3*q*t*t*c2.y+t*t*t*end.y)
                result.addLine(to:warp(p))
            }
            current = end
        }
        path.applyWithBlock { pointer in
            let e = pointer.pointee
            switch e.type {
            case .moveToPoint: current = e.points[0];start = current;result.move(to:warp(current))
            case .addLineToPoint:
                let end = e.points[0], origin = current
                for i in 1...6 { let t = Double(i)/6;result.addLine(to:warp(CGPoint(x:origin.x+(end.x-origin.x)*t,y:origin.y+(end.y-origin.y)*t))) };current = end
            case .addQuadCurveToPoint:
                let c = e.points[0], end = e.points[1]
                curve(end,CGPoint(x:current.x+(c.x-current.x)*2/3,y:current.y+(c.y-current.y)*2/3),CGPoint(x:end.x+(c.x-end.x)*2/3,y:end.y+(c.y-end.y)*2/3))
            case .addCurveToPoint: curve(e.points[2],e.points[0],e.points[1])
            case .closeSubpath: result.closeSubpath();current = start
            @unknown default: break
            }
        }
        return result
    }

    static func florets(species: BloomPlant, variation: Double) -> CGPath {
        let path = CGMutablePath()
        for tier in 0..<7 { for side in [-1.0,1.0] {
            let phase = Double(tier)*7.13+variation*29+side
            let y = Double(tier)*0.14+sin(phase)*0.025
            let x = side*(0.07+0.025*sin(phase*1.9))
            let width = (species == .grass ? 0.045:0.086)*(1-Double(tier)*0.065)
            path.move(to:CGPoint(x:x*0.45,y:y-0.06))
            path.addCurve(to:CGPoint(x:x-width,y:y+0.06),control1:CGPoint(x:x-width*1.2,y:y-0.03),control2:CGPoint(x:x-width*1.3,y:y+0.045))
            path.addQuadCurve(to:CGPoint(x:x+width*0.08,y:y+0.073),control:CGPoint(x:x-width*0.4,y:y+0.13))
            path.addQuadCurve(to:CGPoint(x:x+width,y:y+0.047),control:CGPoint(x:x+width*0.8,y:y+0.11))
            path.addCurve(to:CGPoint(x:x*0.45,y:y-0.06),control1:CGPoint(x:x+width*1.2,y:y),control2:CGPoint(x:x+width*0.4,y:y-0.04))
            path.closeSubpath()
        } }
        return path
    }

    static func paint(path: CGPath, species: BloomPlant, organ: BloomOrgan, color: NSColor,
                      paper: NSColor, ink: NSColor, art: BloomArtSettings, resolution: Double) -> Painting? {
        let bounds = path.boundingBoxOfPath.insetBy(dx:-0.055,dy:-0.055)
        let pixels = min(192,max(48,resolution))
        let w = max(1,Int(ceil(bounds.width*pixels))), h = max(1,Int(ceil(bounds.height*pixels)))
        guard let c = bitmap(width:w,height:h) else { return nil }
        c.scaleBy(x:Double(w)/bounds.width,y:Double(h)/bounds.height)
        c.translateBy(x:-bounds.minX,y:-bounds.minY)
        c.setLineCap(.round);c.setLineJoin(.round)
        let watercolor = art.rendering == .botanicalWatercolor
        let pigment = art.pigmentVariation
        var random = ArtRandom(state:UInt64(organ.variation*Double(UInt32.max)) &+ 1709)
        let needle = species.evergreen && species != .cedar
        let silhouette = needle ? path.copy(strokingWithWidth:0.035,lineCap:.round,lineJoin:.round,miterLimit:2) : path
        // A very thin diluted perimeter is visible only at selected wet edges.
        if watercolor && art.wetEdges > 0 {
            c.saveGState()
            c.clip(to:CGRect(x:bounds.midX-0.06,y:bounds.minY,width:bounds.width,height:bounds.height*0.63))
            c.addPath(silhouette);c.setStrokeColor(color.withAlphaComponent(art.wetEdges*0.16).cgColor)
            c.setLineWidth(0.012+art.wetEdges*0.025);c.strokePath();c.restoreGState()
        }
        c.saveGState();c.addPath(silhouette);c.clip()
        c.setFillColor(color.withAlphaComponent(watercolor ? 0.82:0.89).cgColor);c.fill(bounds)
        // Broad transparent glazes follow the organ's long axis, with reserved
        // paper down one side and denser, cooler pigment toward the petiole.
        for pass in 0..<6 {
            let x = bounds.minX+random.next()*bounds.width
            let y = bounds.minY+random.next()*bounds.height
            let light = pass%3 == 0
            let wash = light ? paper : color.blended(withFraction:pass%2 == 0 ? 0.55:0.28,of:ink)!
            let alpha = pigment*(light ? 0.48:0.50)
            let gradient = CGGradient(colorsSpace:CGColorSpace(name:CGColorSpace.sRGB),colors:[wash.withAlphaComponent(alpha).cgColor,wash.withAlphaComponent(0).cgColor] as CFArray,locations:[0,1])!
            c.drawRadialGradient(gradient,startCenter:CGPoint(x:x,y:y),startRadius:0,endCenter:CGPoint(x:x+0.04,y:y+0.07),endRadius:bounds.height*(0.16+random.next()*0.32),options:[])
        }
        // A handful of brush pulls, with split bristle reserves. Their direction
        // follows the leaf blade or petal, never the screen or animation clock.
        if !needle {
            for pull in 0..<7 {
                let x = (random.next()-0.5)*bounds.width*0.80
                let y = bounds.minY+bounds.height*(0.06+random.next()*0.52)
                let tip = min(bounds.maxY,bounds.minY+bounds.height*(0.48+random.next()*0.49))
                let bend = (random.next()-0.5)*0.29
                var start = CGPoint(x:x*0.5,y:y), end = CGPoint(x:x*0.85+bend*0.35,y:tip)
                var control = CGPoint(x:x+bend,y:(y+tip)*0.52)
                if organ.flower && ![.lavender,.sage,.grass].contains(species) {
                    let angle = Double(pull)*2.39996+organ.variation*6
                    let from = 0.12+random.next()*0.20, to = 0.65+random.next()*0.30
                    start = CGPoint(x:sin(angle)*from,y:cos(angle)*from)
                    end = CGPoint(x:sin(angle)*to,y:cos(angle)*to)
                    control = CGPoint(x:sin(angle+bend)*0.55,y:cos(angle+bend)*0.55)
                }
                let reserve = pull%3 == 0
                let tint = reserve ? paper:color.blended(withFraction:0.4,of:ink)!
                let width = 0.018+random.next()*0.040
                var previous = start
                for step in 1...12 {
                    let t = Double(step)/12, q = 1-t
                    let at = CGPoint(x:q*q*start.x+2*q*t*control.x+t*t*end.x,y:q*q*start.y+2*q*t*control.y+t*t*end.y)
                    let pressure = pow(max(0,sin((t-0.04)*Double.pi)),0.65)
                    c.setLineWidth(width*(0.18+0.82*pressure))
                    let skip = reserve && (step == 4+pull%3 || step == 9) ? 0.12:1.0
                    c.setStrokeColor(tint.withAlphaComponent(pigment*(reserve ? 0.17:0.28)*pressure*skip).cgColor)
                    c.move(to:previous);c.addLine(to:at);c.strokePath()
                    if watercolor && pull%2 == 0 && step>3 && step<9 {
                        c.setLineWidth(0.003);c.setStrokeColor(paper.withAlphaComponent(0.14*pressure).cgColor)
                        c.move(to:CGPoint(x:previous.x+0.008,y:previous.y));c.addLine(to:CGPoint(x:at.x+0.008,y:at.y));c.strokePath()
                    }
                    previous = at
                }
            }
        }
        if organ.flower && [.lavender,.sage,.grass].contains(species) {
            for tier in 0..<7 { for side in [-1.0,1.0] {
                let center = CGPoint(x:side*0.08,y:Double(tier)*0.14)
                let tint = color.blended(withFraction:0.33,of:ink)!
                let gradient = CGGradient(colorsSpace:nil,colors:[tint.withAlphaComponent(pigment*0.56).cgColor,tint.withAlphaComponent(0).cgColor] as CFArray,locations:[0,1])!
                c.drawRadialGradient(gradient,startCenter:center,startRadius:0,endCenter:center,endRadius:0.11,options:[])
                c.setStrokeColor(paper.withAlphaComponent(0.26).cgColor);c.setLineWidth(0.012)
                c.move(to:CGPoint(x:center.x-0.025,y:center.y+0.04));c.addQuadCurve(to:CGPoint(x:center.x+0.03,y:center.y+0.05),control:CGPoint(x:center.x,y:center.y+0.075));c.strokePath()
            } }
        }
        if watercolor {
            // Pigment lodges in fibers; dry reserves expose the actual palette's
            // paper. Density is local to the wash, not a full-frame noise overlay.
            let count = Int(bounds.width*bounds.height*organ.length*organ.length*0.85)
            for _ in 0..<min(1700,count) {
                let x = bounds.minX+random.next()*bounds.width, y = bounds.minY+random.next()*bounds.height
                let pool = 0.5+0.5*sin(x*14+y*9+organ.variation*19)
                let reserve = random.next()>0.56
                c.setStrokeColor((reserve ? paper:ink).withAlphaComponent(art.paperGrain*(reserve ? 0.35:0.20)*(0.3+pool)).cgColor)
                c.setLineWidth((0.10+random.next()*0.18)/organ.length)
                c.move(to:CGPoint(x:x,y:y));c.addLine(to:CGPoint(x:x+(0.20+random.next()*0.65)/organ.length,y:y+0.12/organ.length));c.strokePath()
            }
            c.addPath(silhouette);c.setStrokeColor(color.blended(withFraction:0.24,of:ink)!.withAlphaComponent(pigment*0.33).cgColor)
            c.setLineWidth(0.023);c.setLineDash(phase:organ.variation*0.4,lengths:[0.13,0.08,0.31,0.14]);c.strokePath();c.setLineDash(phase:0,lengths:[])
        }
        c.restoreGState()
        // Broken pressure-sensitive pencil contour: short line groups vary smoothly
        // in weight and density, leaving the paint to describe much of the edge.
        var current = CGPoint.zero, start = CGPoint.zero, segment = 0
        func pencil(to end: CGPoint) {
            let wave = sin(Double(segment)*0.18+organ.variation*43)
            if wave > -0.52 {
                c.setLineWidth(0.0035+(wave+1)*0.0025)
                c.setStrokeColor(ink.withAlphaComponent(0.14+(wave+1)*0.10).cgColor)
                c.move(to:current);c.addLine(to:end);c.strokePath()
                if wave>0.65 && !needle {
                    let offset = 0.006+0.003*sin(Double(segment)*0.29+organ.variation*9)
                    c.setLineWidth(0.003);c.setStrokeColor(ink.withAlphaComponent(0.16).cgColor)
                    c.move(to:CGPoint(x:current.x+offset,y:current.y+offset*0.35));c.addLine(to:CGPoint(x:end.x+offset,y:end.y+offset*0.35));c.strokePath()
                }
            }
            current = end;segment += 1
        }
        path.applyWithBlock { pointer in
            let e = pointer.pointee
            switch e.type {
            case .moveToPoint:current = e.points[0];start = current
            case .addLineToPoint:pencil(to:e.points[0])
            case .closeSubpath:pencil(to:start)
            default:break
            }
        }
        // Anatomy-specific venation, clipped so narrow leaves never sprout stray
        // diagonal marks. Petal veins radiate; grasses and needles stay linear.
        c.saveGState();c.addPath(silhouette);c.clip()
        if !organ.flower && !needle {
            let narrow = [.lavender,.sage,.willow,.fern].contains(species)
            for side in [-1.0,1.0] {
                let n = narrow ? 3:5
                for i in 1...n {
                    let y = Double(i)/Double(n+2)+side*0.024*sin(organ.variation*21)
                    let width = (narrow ? 0.11:0.27)*sin(y*Double.pi)
                    c.setStrokeColor(ink.withAlphaComponent(0.18+random.next()*0.12).cgColor)
                    c.setLineWidth(0.004+random.next()*0.005)
                    c.setLineDash(phase:organ.variation*0.17,lengths:[0.08,0.016,0.11,0.035])
                    c.move(to:CGPoint(x:0.01,y:y));c.addQuadCurve(to:CGPoint(x:side*width,y:y+0.17),control:CGPoint(x:side*width*0.65,y:y+0.05));c.strokePath()
                }
            }
            c.setLineDash(phase:0,lengths:[])
            let curve = 0.025+sin(organ.variation*39)*0.026
            c.setStrokeColor(paper.withAlphaComponent(0.18).cgColor);c.setLineWidth(0.007)
            c.setLineDash(phase:organ.variation*0.31,lengths:[0.09,0.03,0.17,0.045])
            c.move(to:CGPoint(x:0.009,y:0.04));c.addQuadCurve(to:CGPoint(x:0.01,y:0.94),control:CGPoint(x:curve+0.009,y:0.46));c.strokePath()
            c.setStrokeColor(ink.withAlphaComponent(0.40).cgColor);c.setLineWidth(0.007)
            c.setLineDash(phase:organ.variation*0.09,lengths:[0.22,0.024,0.31,0.035])
            c.move(to:.zero);c.addQuadCurve(to:CGPoint(x:0,y:0.89),control:CGPoint(x:curve,y:0.44));c.strokePath()
        } else if organ.flower && ![.lavender,.sage,.grass].contains(species) {
            let count = species == .dogwood ? 4:species == .sunflower ? 17:9
            for i in 0..<count {
                let angle = Double(i)/Double(count)*Double.pi*2+organ.variation*0.05
                c.setStrokeColor(ink.withAlphaComponent(0.15).cgColor);c.setLineWidth(0.006)
                c.move(to:CGPoint(x:sin(angle)*0.17,y:cos(angle)*0.17))
                c.addQuadCurve(to:CGPoint(x:sin(angle)*0.81,y:cos(angle)*0.81),control:CGPoint(x:sin(angle+0.10)*0.51,y:cos(angle+0.10)*0.51));c.strokePath()
            }
        }
        c.restoreGState()
        if organ.flower && ![.lavender,.sage,.grass].contains(species) {
            let r = species == .sunflower ? 0.37:species == .coneflower ? 0.28:0.13
            let center = CGMutablePath()
            if species == .coneflower {
                center.move(to:CGPoint(x:-r,y:-0.08))
                center.addCurve(to:CGPoint(x:r,y:-0.08),control1:CGPoint(x:-r*0.8,y:0.32),control2:CGPoint(x:r*0.65,y:0.34))
                center.addQuadCurve(to:CGPoint(x:-r,y:-0.08),control:CGPoint(x:0,y:-0.16));center.closeSubpath()
            } else { center.addEllipse(in:CGRect(x:-r,y:-r,width:r*2,height:r*2)) }
            let core = organicPath(center,species:species,flower:true,variation:organ.variation,amount:art.edgeIrregularity)
            c.addPath(core);c.setFillColor(ink.withAlphaComponent(0.78).cgColor);c.fillPath()
            c.saveGState();c.addPath(core);c.clip()
            for i in 0..<(species == .sunflower ? 65:25) {
                let angle = Double(i)*2.39996, radius = sqrt(Double(i)/65)*r
                let dot = (species == .sunflower ? 0.018:0.013)*(0.6+random.next())
                c.setFillColor(paper.blended(withFraction:0.4,of:color)!.withAlphaComponent(0.35+random.next()*0.35).cgColor)
                c.fillEllipse(in:CGRect(x:cos(angle)*radius,y:sin(angle)*radius,width:dot,height:dot*0.75))
            }
            c.restoreGState()
        }
        guard let image = c.makeImage() else { return nil }
        return Painting(image:image,bounds:bounds)
    }
}

/// Per-scene cost-limited LRU; no global cache or background work survives a scene.
/// Layers share the cached CGImages. The scene clears old layers before pruning.
final class BloomPaintingCache {
    struct Key: Hashable { let species: String; let variation: Double; let flower: Bool; let autumn: Bool }
    private var entries: [Key:(BloomIllustration.Painting,Int)] = [:]
    private var tick = 0
    let limit: Int
    private(set) var bytes = 0
    private(set) var hits = 0
    private(set) var misses = 0
    init(limit: Int = 24*1024*1024) { self.limit = max(0,limit) }
    func removeAll() { entries.removeAll();bytes = 0 }
    func painting(_ key: Key, make: () -> BloomIllustration.Painting?) -> BloomIllustration.Painting? {
        tick += 1
        if let entry = entries[key] { hits += 1;entries[key] = (entry.0,tick);return entry.0 }
        misses += 1
        guard let value = make() else { return nil }
        guard value.bytes <= limit else { return value }
        while bytes+value.bytes>limit, let oldest = entries.min(by: { $0.value.1<$1.value.1 }) {
            bytes -= oldest.value.0.bytes;entries.removeValue(forKey:oldest.key)
        }
        entries[key] = (value,tick);bytes += value.bytes
        return value
    }
}
